package com.collaborativecanvas.client;
import com.collaborativecanvas.client.config.*;import com.collaborativecanvas.client.controller.*;import com.collaborativecanvas.client.model.ClientSession;import javafx.application.Application;import javafx.fxml.FXMLLoader;import javafx.scene.*;import javafx.stage.Stage;import java.io.IOException;
public class CollaborativeCanvasClient extends Application {private Stage stage;private ClientConfig config;public ClientConfig config(){return config;}@Override public void start(Stage stage)throws Exception{this.stage=stage;this.config=ClientConfigLoader.load();stage.setTitle("Collaborative Canvas");stage.setMinWidth(960);stage.setMinHeight(650);showHome();stage.show();}public void showHome(){try{FXMLLoader l=new FXMLLoader(getClass().getResource("/fxml/home-view.fxml"));Scene s=new Scene(l.load(),720,620);s.getStylesheets().add(getClass().getResource("/styles/app.css").toExternalForm());l.<HomeController>getController().setApp(this);stage.setScene(s);}catch(IOException e){throw new IllegalStateException("Unable to load the home screen",e);}}public void openWorkspace(String name,String url,String room,String participant){try{FXMLLoader l=new FXMLLoader(getClass().getResource("/fxml/canvas-view.fxml"));Scene s=new Scene(l.load(),1280,820);s.getStylesheets().add(getClass().getResource("/styles/app.css").toExternalForm());CanvasController c=l.getController();stage.setScene(s);c.setAppAndSession(this,new ClientSession(name,url,room,participant));}catch(IOException e){throw new IllegalStateException("Unable to load the canvas screen",e);}}public static void main(String[] args){launch(args);}}
